export type Locale = keyof typeof localeInfo;

export const pageTitles: Record<Locale, Record<string, string>> = {
  ru: { 'index.html': 'Дизайн, который обретает форму — Acor Web', 'about.html': 'Студия — Acor Web', 'contact.html': 'Обсудить проект — Acor Web', 'cases.html': 'Проекты — Acor Web', 'services.html': 'Услуги — Acor Web', 'team.html': 'Команда — Acor Web', 'careers.html': 'Карьера — Acor Web', 'lab.html': 'Lab — Acor Web', 'privacy.html': 'Конфиденциальность — Acor Web' },
  en: { 'index.html': 'Design that takes shape — Acor Web', 'about.html': 'Studio — Acor Web', 'contact.html': 'Discuss a project — Acor Web', 'cases.html': 'Projects — Acor Web', 'services.html': 'Services — Acor Web', 'team.html': 'Team — Acor Web', 'careers.html': 'Careers — Acor Web', 'lab.html': 'Lab — Acor Web', 'privacy.html': 'Privacy — Acor Web' },
  pl: { 'index.html': 'Design, który nabiera formy — Acor Web', 'about.html': 'Studio — Acor Web', 'contact.html': 'Omówmy projekt — Acor Web', 'cases.html': 'Projekty — Acor Web', 'services.html': 'Usługi — Acor Web', 'team.html': 'Zespół — Acor Web', 'careers.html': 'Kariera — Acor Web', 'lab.html': 'Lab — Acor Web', 'privacy.html': 'Prywatność — Acor Web' },
  be: { 'index.html': 'Дызайн, які набывае форму — Acor Web', 'about.html': 'Студыя — Acor Web', 'contact.html': 'Абмеркаваць праект — Acor Web', 'cases.html': 'Праекты — Acor Web', 'services.html': 'Паслугі — Acor Web', 'team.html': 'Каманда — Acor Web', 'careers.html': 'Кар’ера — Acor Web', 'lab.html': 'Lab — Acor Web', 'privacy.html': 'Канфідэнцыяльнасць — Acor Web' }
} as const;

const localeMaps = Object.fromEntries(
  (Object.keys(localeInfo) as Locale[]).map((locale, index) => [
    locale,
    Object.fromEntries(localeRows.map((row) => [row[0], row[index] || row[0]]))
  ])
) as Record<Locale, Record<string, string>>;

type LocalizableAttribute = 'placeholder' | 'aria-label' | 'title' | 'alt';

export interface LocaleController {
  readonly info: typeof localeInfo;
  readonly translate: (value: string) => string;
  readonly pageKey: () => string;
  readonly apply: () => void;
  readonly setLanguageSelect: (select: HTMLSelectElement | null) => void;
  readonly setLocale: (locale: string) => boolean;
}

export const createLocaleController = (): LocaleController => {
  let activeLocale: Locale = 'ru';
  try {
    const savedLocale = localStorage.getItem('acor-lang');
    if (savedLocale && savedLocale in localeInfo) activeLocale = savedLocale as Locale;
  } catch {
    // Locale remains Russian when storage is unavailable.
  }

  const textSources = new WeakMap<Text, string>();
  const attributeSources = new WeakMap<Element, Partial<Record<LocalizableAttribute, string | null>>>();
  let languageSelect: HTMLSelectElement | null = null;

  const translate = (value: string): string => localeMaps[activeLocale][value] || value;
  const pageKey = (): string => {
    const pathname = location.pathname.split('/').filter(Boolean);
    const last = pathname.at(-1) || 'index';
    if (last === 'index.html') return 'index.html';
    if (last.endsWith('.html')) return last;
    if (last === 'arden' || last === 'greenflow' || last === 'orbit') return `case-${last}.html`;
    return `${last}.html`;
  };

  const apply = (): void => {
    document.documentElement.lang = localeInfo[activeLocale].html;
    const title = pageTitles[activeLocale]?.[pageKey()];
    if (title) document.title = title;

    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, {
      acceptNode: (node) => ['SCRIPT', 'STYLE', 'NOSCRIPT'].includes(node.parentElement?.tagName || '')
        ? NodeFilter.FILTER_REJECT
        : NodeFilter.FILTER_ACCEPT
    });
    const textNodes: Text[] = [];
    while (walker.nextNode()) textNodes.push(walker.currentNode as Text);
    textNodes.forEach((node) => {
      const current = node.nodeValue || '';
      const original = textSources.get(node) || current.replace(/\s+/g, ' ').trim();
      if (!textSources.has(node)) textSources.set(node, original);
      const translated = translate(original);
      if (!translated) return;
      const leading = current.match(/^\s*/)?.[0] || '';
      const trailing = current.match(/\s*$/)?.[0] || '';
      node.nodeValue = `${leading}${translated}${trailing}`;
    });

    document.querySelectorAll<HTMLElement>('[placeholder],[aria-label],[title],[alt]').forEach((element) => {
      const attributes = attributeSources.get(element) || {};
      (['placeholder', 'aria-label', 'title', 'alt'] as const).forEach((name) => {
        if (!element.hasAttribute(name)) return;
        if (!(name in attributes)) attributes[name] = element.getAttribute(name);
        const value = attributes[name];
        if (value && localeMaps[activeLocale][value]) element.setAttribute(name, translate(value));
      });
      attributeSources.set(element, attributes);
    });
    if (languageSelect) languageSelect.value = activeLocale;
    window.dispatchEvent(new CustomEvent('acor:locale-change', { detail: { locale: activeLocale } }));
  };

  const setLocale = (locale: string): boolean => {
    if (!(locale in localeInfo)) return false;
    activeLocale = locale as Locale;
    try {
      localStorage.setItem('acor-lang', activeLocale);
    } catch {
      // The selector still works for this page.
    }
    apply();
    return true;
  };

  return {
    info: localeInfo,
    translate,
    pageKey,
    apply,
    setLanguageSelect: (select) => { languageSelect = select; },
    setLocale
  };
};
